// Per-event analytics. God mode only, same moderator gate as App analytics.
// The funnel tip is the existing app Attend count. Meetup going, when this
// event has a Meetup id, is the same YES count as the attendance list.
import { useCallback, useEffect, useState } from 'react';
import { RefreshControl, Text, View } from 'react-native';
import { Redirect, router, Stack, useLocalSearchParams } from 'expo-router';
import { ErrorText, Page, PageHeader, SectionCard, styles } from '../../../components/ui';
import { AnalyticsFunnel, AnalyticsViewLog, formatCount, Stat } from '../../../components/stat';
import { useCanModerate } from '../../../components/mod';
import { getEventAnalytics, viewerCountSentence, type EventAnalytics } from '../../../lib/analytics';
import { getEvent } from '../../../lib/events';
import { fmtDate } from '../../../lib/format';
import { colors, fs } from '../../../lib/theme';

export default function EventAnalyticsPage() {
  const raw = useLocalSearchParams<{ id: string }>().id;
  const id = Array.isArray(raw) ? raw[0] : raw;
  const { ready, ok } = useCanModerate();
  const [title, setTitle] = useState('Event');
  const [when, setWhen] = useState<string | null>(null);
  const [data, setData] = useState<EventAnalytics | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const load = useCallback(async () => {
    if (!id) return;
    setBusy(true);
    setErr(null);
    const event = getEvent(id).then((row) => {
      if (row) {
        setTitle(row.title);
        setWhen(row.starts_at);
      }
    }).catch(() => {});
    const stats = getEventAnalytics(id).then(setData).catch((e: { message?: string }) => {
      setErr(e.message ?? 'Couldn’t load event analytics.');
      setData(null);
    });
    await Promise.all([event, stats]);
    setBusy(false);
  }, [id]);

  useEffect(() => { if (ok) load(); }, [ok, load]);

  if (!ready) return <View style={{ flex: 1, backgroundColor: colors.paper }} />;
  if (!ok || !id) return <Redirect href={id ? `/events/${id}` : '/events'} />;

  const viewers = data?.viewers ?? 0;
  return (
    <Page refreshControl={<RefreshControl refreshing={busy} onRefresh={load} />}>
      <Stack.Screen options={{ title: 'Analytics' }} />
      <Text onPress={() => router.navigate(`/events/${id}`)} accessibilityRole="link" style={[styles.link, { fontSize: fs(13) }]}>Back to event</Text>
      <PageHeader
        icon="bar-chart"
        eyebrow="Analytics"
        title={title}
        subtitle={when ? fmtDate(when) : 'This event'}
      />
      <ErrorText>{err}</ErrorText>
      {busy && !data ? <Text style={styles.muted}>Loading…</Text> : null}
      {data ? (
        <>
          <SectionCard title="Who viewed this page">
            <Text style={[styles.muted, { fontSize: fs(13), marginBottom: 12 }]}>
              {viewerCountSentence(viewers, data.views, 'on the member page and the public page.')}
            </Text>
            <Stat label="App users" value={viewers} note="Signed-in viewers" />
          </SectionCard>
          <SectionCard title="Funnel">
            <AnalyticsFunnel anonymous={data.funnel.anonymousViews} authenticated={data.funnel.authenticatedViews} rsvps={data.funnel.rsvps}
              anonymousNote="Public page" authenticatedNote="App users" rsvpNote="App attend" />
            {data.meetupGoing != null ? (
              <Text style={[styles.muted, { fontSize: fs(13), marginTop: 12 }]}>Meetup going {formatCount(data.meetupGoing)}</Text>
            ) : null}
          </SectionCard>
          <SectionCard title="Views">
            <AnalyticsViewLog rows={data.log} />
          </SectionCard>
        </>
      ) : null}
    </Page>
  );
}
